import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  reactStrictMode: true,
  serverExternalPackages: [],
  async headers() {
    return [
      {
        // Pre-rendered social cards (public/og/*.png, generated by `npm run og`).
        // Same caching story as the dynamic `/api/og` route had: crawlers
        // re-fetch them rarely, and a stale card is served only while a new
        // build revalidates in the background.
        source: "/og/:file*",
        headers: [
          {
            key: "Cache-Control",
            value:
              "public, max-age=3600, s-maxage=86400, stale-while-revalidate=604800",
          },
        ],
      },
    ];
  },
};

export default nextConfig;
